# Load required libraries
library(haven)
library(dplyr)
library(tidyr)
library(purrr)
library(labelled)
library(readr)

# Define file paths
file_paths <- list(
  wave_one = \"data/input/wave_one_lsype_young_person_2020.tab\",
  wave_two = \"data/input/wave_two_lsype_young_person_2020.tab\",
  wave_four = \"data/input/wave_four_lsype_young_person_2020.tab\",
  ns8_derived = \"data/input/ns8_2015_derived.tab\",
  ns9_derived = \"data/input/ns9_2022_derived_variables.tab\"
)

# Load each file explicitly
wave_one_data <- readr::read_delim(file_paths$wave_one, delim = \"\\t\")
wave_two_data <- readr::read_delim(file_paths$wave_two, delim = \"\\t\")
wave_four_data <- readr::read_delim(file_paths$wave_four, delim = \"\\t\")
ns8_data <- readr::read_delim(file_paths$ns8_derived, delim = \"\\t\")
ns9_data <- readr::read_delim(file_paths$ns9_derived, delim = \"\\t\")

# Create a list of all datasets
datasets <- list(
  wave_one = wave_one_data,
  wave_two = wave_two_data,
  wave_four = wave_four_data,
  ns8 = ns8_data,
  ns9 = ns9_data
)

# Merge datasets using full_join by NSID
merged_data <- datasets[[1]] %>%
  full_join(datasets[[2]], by = \"NSID\") %>%
  full_join(datasets[[3]], by = \"NSID\") %>%
  full_join(datasets[[4]], by = \"NSID\") %>%
  full_join(datasets[[5]], by = \"NSID\")

# Define a function to map missing values to standard codes
map_missing_values <- function(x) {
  if (is.na(x)) return(-3)

  # Wave 1 missing codes
  if (grepl(\"^wave_one$\", deparse(substitute(x)))) {
    if (x == -999) return(-2)  # Missing - household data lost
    if (x == -94)  return(-8)  # Insufficient information
    if (x == -92)  return(-9)  # Refused
    if (x == -91)  return(-1)  # Not applicable
    if (x == -1)   return(-8)  # Don't know
  }

  # Wave 2 missing codes
  if (grepl(\"^wave_two$\", deparse(substitute(x)))) {
    if (x == -998 || x == -997 || x == -995) return(-2)  # Interviewer missed question, script error, missing history section
    if (x == -99)  return(-3)  # YP not interviewed
    if (x == -92)  return(-9)  # Refused
    if (x == -91)  return(-1)  # Not applicable
    if (x == -1)   return(-8)  # Don't know
  }

  # Wave 4 missing codes
  if (grepl(\"^wave_four$\", deparse(substitute(x)))) {
    if (x == -94)  return(-8)  # Insufficient information
    if (x == -1)   return(-8)  # Don't know
  }

  # Wave 8 missing codes
  if (grepl(\"^ns8$\", deparse(substitute(x)))) {
    if (x == -9)   return(-9)  # Refused
    if (x == -8)   return(-8)  # Insufficient information
    if (x == -1)   return(-1)  # Not applicable
  }

  # Wave 9 missing codes
  if (grepl(\"^ns9$\", deparse(substitute(x)))) {
    if (x == -8)   return(-8)  # Insufficient information
  }

  return(x)
}

# Define a function to map ethnicity categories to a harmonized scheme
harmonize_ethnicity <- function(x) {
  if (is.na(x)) return(-3)

