wave_one_ethnicity <- merged_data %>%
  transmute(NSID, eth_wave1 = map_dbl(W1ethnic2YP, map_missing_values)) %>%
  rename(eth_wave1 = eth_wave1)

wave_two_ethnicity <- merged_data %>%
  transmute(NSID, eth_wave2 = map_dbl(W2ethnicYP, map_missing_values)) %>%
  rename(eth_wave2 = eth_wave2)

wave_four_ethnicity <- merged_data %>%
