  if (x == -99) return(-3)
  if (x == -8) return(-8)
  if (x == -9) return(-9)
  return(x)
}

# Create a function to safely extract variables
safe_extract <- function(df, col_name, default_value) {
  if (col_name %in% names(df)) {
    return(map_dbl(df[[col_name]], map_missing))
  } else {
    return(rep(default_value, nrow(df)))
  }
}

