  # Wave 1 missing codes
  if (grepl(\"^wave_one$\", deparse(substitute(x)))) {
    if (x == -999) return(-2)  # Missing - household data lost
    if (x == -94)  return(-8)  # Insufficient information
    if (x == -92)  return(-9)  # Refused
    if (x == -91)  return(-1)  # Not applicable
    if (x == -1)   return(-8)  # Don't know
