wave_two <- read_delim(file_paths[[2]], delim = "\t")
wave_four <- read_delim(file_paths[[3]], delim = "\t")
ns8 <- read_delim(file_paths[[4]], delim = "\t")
ns9 <- read_delim(file_paths[[5]], delim = "\t")

# Merge datasets
merged <- wave_one %>%
  full_join(wave_two, by = "NSID") %>%
  full_join(wave_four, by = "NSID") %>%
  full_join(ns8, by = "NSID") %>%
  full_join(ns9, by = "NSID")

# Function to map missing values
map_missing <- function(x) {
  if (is.na(x)) return(-3)
  if (x == -999) return(-2)
  if (x == -94) return(-8)
  if (x == -92) return(-9)
  if (x == -91) return(-1)
  if (x == -1) return(-8)
  if (x == -998 || x == -997 || x == -995) return(-2)
  if (x == -99) return(-3)
  if (x == -8) return(-8)
  if (x == -9) return(-9)
  return(x)
}

# Extract ethnicity variables with explicit checks
eth_wave1 <- if ("W1ethnicYP" %in% names(merged)) {
  as.numeric(merged$W1ethnicYP) %>% map_missing()
} else {
  rep(-3, nrow(merged))
}

eth_wave2 <- if ("W2ethnicYP" %in% names(merged)) {
  as.numeric(merged$W2ethnicYP) %>% map_missing()
} else {
  rep(-3, nrow(merged))
}

eth_wave4 <- if ("w4ethnic2YP" %in% names(merged)) {
  as.numeric(merged$w4ethnic2YP) %>% map_missing()
} else {
  rep(-3, nrow(merged))
}

eth_wave8 <- if ("W8DETHN15" %in% names(merged)) {
  as.numeric(merged$W8DETHN15) %>% map_missing()
} else {
  rep(-3, nrow(merged))
}

eth_wave9 <- if ("W9DETHN15" %in% names(merged)) {
  as.numeric(merged$W9DETHN15) %>% map_missing()
} else {
  rep(-3, nrow(merged))
}

# Create data frame with ethnicity variables
eth_data <- data.frame(
  NSID = merged$NSID,
  eth_wave1 = eth_wave1,
  eth_wave2 = eth_wave2,
  eth_wave4 = eth_wave4,
  eth_wave8 = eth_wave8,
  eth_wave9 = eth_wave9,
  stringsAsFactors = FALSE
)

